import re

UNITS = {
    'w': 604800, 'week': 604800, 'weeks': 604800, 'wk': 604800, 'wks': 604800,
    'd': 86400, 'day': 86400, 'days': 86400,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
}

_NUM = r'\d+(?:\.\d+)?'


def _finish(total):
    if total < 0:
        raise ValueError("negative duration")
    return int(round(total))


def _parse_iso(text):
    m = re.fullmatch(
        r'P(?:(%s)W)?(?:(%s)D)?(?:T(?:(%s)H)?(?:(%s)M)?(?:(%s)S)?)?' % (
            _NUM, _NUM, _NUM, _NUM, _NUM),
        text, re.IGNORECASE)
    if not m or not any(m.groups()):
        raise ValueError("invalid ISO 8601 duration: %r" % text)
    weeks, days, hours, minutes, seconds = m.groups()
    total = 0.0
    total += float(weeks or 0) * 604800
    total += float(days or 0) * 86400
    total += float(hours or 0) * 3600
    total += float(minutes or 0) * 60
    total += float(seconds or 0)
    return _finish(total)


def _parse_clock(text):
    parts = text.split(':')
    if len(parts) not in (2, 3):
        raise ValueError("invalid clock notation: %r" % text)
    if not all(re.fullmatch(_NUM, p) for p in parts):
        raise ValueError("invalid clock notation: %r" % text)
    values = [float(p) for p in parts]
    if len(values) == 2:
        minutes, seconds = values
        total = minutes * 60 + seconds
    else:
        hours, minutes, seconds = values
        total = hours * 3600 + minutes * 60 + seconds
    return _finish(total)


def _parse_components(text):
    pos = 0
    total = 0.0
    found = False
    pattern = re.compile(r'\s*(%s)\s*([a-zA-Z]+)' % _NUM)
    while pos < len(text):
        m = pattern.match(text, pos)
        if not m:
            raise ValueError("invalid duration: %r" % text)
        number, unit = m.group(1), m.group(2).lower()
        if unit not in UNITS:
            raise ValueError("unknown unit: %r" % unit)
        total += float(number) * UNITS[unit]
        found = True
        pos = m.end()
    if not found:
        raise ValueError("invalid duration: %r" % text)
    return _finish(total)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("expected a string")
    text = text.strip()
    if not text:
        raise ValueError("empty input")
    if re.fullmatch(r'\d+', text):
        return _finish(int(text))
    if text[0] in 'Pp' and re.fullmatch(r'[Pp].*', text):
        return _parse_iso(text)
    if ':' in text:
        return _parse_clock(text)
    return _parse_components(text)

